#include <iostream>

int main() {
    int option = 2;

    // Using do...while with explicit braces for clarity
    do {
        switch (option) {
            case 1:
                std::cout << "Option 1 selected\n";
                break;
            case 2:
                std::cout << "Option 2 selected\n";
                break;
            default:
                std::cout << "Invalid option\n";
                break;
        }
        --option;
    } while (option > 0);

    return 0;
}

#include <iostream>
#include <string>

class GradeBook {
public:
    explicit GradeBook(std::string name)
        : courseName(name.size() <= 25 ? name : name.substr(0, 25)),
          aCount(0), bCount(0), cCount(0), dCount(0), fCount(0) {}

    void processInput() {
        int grade;
        while ((grade = std::cin.get()) != EOF) {
            switch (grade) {
                case 'A':
                case 'a':
                    ++aCount;
                    break;
                case 'B':
                case 'b':
                    ++bCount;
                    break;
                case 'C':
                case 'c':
                    ++cCount;
                    break;
                case 'D':
                case 'd':
                    ++dCount;
                    break;
                case 'F':
                case 'f':
                    ++fCount;
                    break;
                case '\n':
                case '\t':
                case ' ':
                    break; // Ignore whitespace
                default:
                    std::cout << "Invalid grade: " << static_cast<char>(grade) << "\n";
                    break;
            }
        }
    }

    void displaySummary() const {
        std::cout << "Report for " << courseName << ":\n"
                  << "A: " << aCount << "\n"
                  << "B: " << bCount << "\n"
                  << "C: " << cCount << "\n"
                  << "D: " << dCount << "\n"
                  << "F: " << fCount << "\n";
    }

private:
    std::string courseName;
    unsigned int aCount;
    unsigned int bCount;
    unsigned int cCount;
    unsigned int dCount;
    unsigned int fCount;
};

int main() {
    GradeBook book("CS101 C++ Programming");
    book.processInput();
    book.displaySummary();
    return 0;
}
